function counter() {
  let count = 0;             // 밖에서 못 만진다
  return () => ++count;      // 이 함수가 count 를 계속 들고 있다
}
const next = counter();
next(); next();              // 2

// 흔한 함정: var 는 블록을 모른다
for (var i = 0; i < 3; i++) setTimeout(() => console.log(i));  // 3 3 3
for (let j = 0; j < 3; j++) setTimeout(() => console.log(j));  // 0 1 2

console.log('1');
setTimeout(() => console.log('2'), 0);
Promise.resolve().then(() => console.log('3'));
console.log('4');

// 1 4 3 2
// 지금 하던 일 → 미세 작업(Promise) → 큰 작업(setTimeout)

async function load() {
  try {
    const res = await fetch('/api/items');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    console.warn('불러오기 실패', err);
    return [];                 // 화면이 죽지 않게 기본값
  }
}

const items = [{ price: 3 }, { price: 5 }];
items.map((it) => it.price);                 // [3, 5]  모양 바꾸기
items.filter((it) => it.price > 3);          // 고르기
items.reduce((sum, it) => sum + it.price, 0); // 8  합치기

const { price = 0 } = items[0] ?? {};        // 구조 분해 + 기본값
